cription":"Optional conversation input triggers.","cardinality":"many","optional":true,"accepts":{"anyOfCapabilities":["conversation-composer-trigger"]}}},"dataMessageUINames":[],"selected":true},"compositionParents":[{"instanceId":"p10","slot":"composer","pluginId":"conversation-surface","entryPath":"src/agent-ui/plugins/conversation-surface/index.tsx","entryHash":"70a53a3bccca8ac6076f79a2e9bdea4f43108a22a0a318b0f8c39ee42833b12b","implementationOwnership":"npm","interpretation":"Current mounted parent boundary, not a selected mutation target or authority. A child action API does not describe append/replacement behavior in its parent. Use the parent's composition contract only if that boundary answers the requested change; preserve existing actions and permission checks."}],"application":{"entryPath":"src/agent-ui/plugins/composer/index.tsx","implementationOwnership":"npm","implementationImport":"@za38.03/agent-ui-plugins/composer","sharedTypes":{"status":"available","queryResolution":{"status":"complete","requested":1,"resolved":1,"unresolved":0},"statusMeaning":"available means the installed declaration module was inspected; queryResolution and each symbol status describe whether the requested contracts resolved.","packageVersion":"0.0.1","module":"@za38.03/agent-ui-plugins","symbols":[{"name":"useConversationComposer","status":"available","type":"() => ConversationComposerController","truncated":false,"memberNames":[],"memberNamesTruncated":false,"members":[],"membersTruncated":false,"returns":[{"type":"ConversationComposerController","truncated":false}],"signaturesTruncated":false}],"interpretation":"Installed public types and package-owned presentation contracts, not mutation authority. Queries: export.member; $parameter0 through $parameter9 for invocation props; $return for callable return; $element for array/index values; returned $variant0 through $variant7 paths for union branches. Types establish signatures, not runtime semantics; missing behavior facts must remain unverified. Unresolved queries and omitted details are explicit. Each presentation contract is returned once per root export in this response."},"entryHash":"3f03d21bea33f4ffae5411031d32e109fb84112d16e4aeeb0e79dd05d367d1f0","usageGuide":{"entryPath":"src/agent-ui/plugins/composer/index.tsx","implementationImport":"@za38.03/agent-ui-plugins/composer","currentExample":{"language":"tsx","source":"import { useAgentUILocaleCode, useConversationComposer } from "@za38.03/agent-ui-plugins";
import { ConversationComposerPlugin as Composer } from "@za38.03/agent-ui-plugins/composer";
import type { ComponentProps } from "react";

const MAX_COMPOSER_LENGTH = 200;

/** Project-owned counter messages keyed by the unified Agent UI locale code. */
const composerCounterMessages = {
  "zh-CN": { limitReached: "已达到字数上限" },
  "en-US": { limitReached: "Character limit reached" },
} as const;

export function ConversationComposerPlugin(props: ComponentProps<typeof Composer>) {
  const { inputProps, ...rest } = props;
  const { text } = useConversationComposer();
  const localeCode = useAgentUILocaleCode();
  const usedLength = text.length;
  const atLimit = usedLength >= MAX_COMPOSER_LENGTH;
  const messages = composerCounterMessages[localeCode];

  return (
    <div className="aui-composer-counter-root">
      <Composer {...rest} inputProps={{ ...inputProps, maxLength: MAX_COMPOSER_LENGTH }} />
      <div className="aui-composer-counter" data-at-limit={atLimit}>
        <span className="aui-composer-counter-value">
          {usedLength}/{MAX_COMPOSER_LENGTH}
        </span>
        {atLimit ? (
          <span className="aui-composer-counter-limit" role="status">
            {messages.limitReached}
          </span>
        ) : null}
      </div>
    </div>
  );
}
