17:   const usedLength = text.length;
18:   const atLimit = usedLength >= MAX_COMPOSER_LENGTH;
19:   const messages = composerCounterMessages[localeCode];
20: 
21:   return (
22:     <div className="aui-composer-counter-root">
23:       <Composer {...rest} inputProps={{ ...inputProps, maxLength: MAX_COMPOSER_LENGTH }} />
24:       <div className="aui-composer-counter" data-at-limit={atLimit}>
25:         <span className="aui-composer-counter-value">
